def check(name, items):
    seen=set(); dup=[]
    print(f"== {name}: {len(items)} candidates")
    for w in items:
        wl=w.lower()
        if wl in seen: dup.append(w); continue
        seen.add(wl)
        k=re.sub(r"[\s\-]","",wl)
        if wl in exact: print(f"  EXISTS   {w}")
        elif k in norm: print(f"  VARIANT  {w} ~ {norm[k]}")
    if dup: print("  DUPS:", dup)
check("C1", c1); check("C2", c2)
# cross-check overlap between lists
print("cross:", sorted(set(map(str.lower,c1)) & set(map(str.lower,c2))))
